contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // run takes the owner address used to construct c, a recipient, and an amount of ether
    function run(address ownerAddr, address payable recipient, uint256 amount) public payable {
        require(msg.sender == address(this)); // ensure this transaction originates from this contract (checker runs it)
        // The checker deploys a fresh C with ownerAddr and passes it to our constructor, so c.owner() == ownerAddr.
        // To fund c, send `amount` wei from this contract to c via its fallback payable.
        // Ensure this contract has enough balance to forward `amount`.
        require(address(this).balance >= amount);

        // Fund contract c with `amount`.
        (bool sent, ) = address(c).call{value: amount}("");
        require(sent);

        // Read balances before.
        uint256 beforeC = address(c).balance;
        uint256 beforeRecipient = recipient.balance;
        address owner = c.owner();

        bool reverted;
        // Attempt withdrawAll from this contract (msg.sender will be this contract).
        try c.withdrawAll(recipient) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint256 afterC = address(c).balance;
        uint256 afterRecipient = recipient.balance;

        // General rule:
        // If this contract is the owner of c, withdrawAll must succeed, leaving c's balance zero and
        // increasing the recipient balance by exactly beforeC. Otherwise the call reverts and balances unchanged.
        assert(
            // If this InvMutTest contract is owner
            (owner == address(this) && reverted == false && afterC == 0 && afterRecipient == beforeRecipient + beforeC)
            ||
            // If not owner: call must revert and balances unchanged
            (owner != address(this) && reverted == true && afterC == beforeC && afterRecipient == beforeRecipient)
        );
    }

    receive() external payable { }
}

