contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // run takes an owner candidate, a recipient, and an amount to send to C before withdrawal
    function run(address ownerAddr, address payable recipient, uint256 amount) public payable {
        require(address(this).balance >= amount);

        // Ensure the deployed c has the specified owner: the constructor of c set owner already;
        // we observe it via the public getter.
        address actualOwner = c.owner();

        // Precondition: we only proceed for any inputs; the property must hold for all inputs.
        // Fund the contract c with `amount` wei from this test contract.
        // Sending ether to c uses the fallback payable.
        (bool ok,) = address(c).call{value: amount}("");
        // record balances before attempting withdrawal
        uint256 cBalanceBefore = address(c).balance;
        uint256 recipientBalanceBefore = recipient.balance;

        // Attempt withdrawal and capture whether it reverts. According to C, only owner may withdraw.
        bool reverted;
        try c.withdrawAll(recipient) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint256 cBalanceAfter = address(c).balance;
        uint256 recipientBalanceAfter = recipient.balance;

        // General rule:
        // If the caller (this contract) is the recorded owner, withdrawAll must not revert and
        // transfer all funds from c to the recipient (so c balance becomes zero and recipient increases by the amount removed).
        // If the caller is not the owner, withdrawAll must revert and balances must be unchanged.
        bool callerIsOwner = (actualOwner == address(this));

        assert(
            callerIsOwner
            ? (
                reverted == false
                && cBalanceAfter == 0
                && recipientBalanceAfter >= recipientBalanceBefore
                && recipientBalanceAfter - recipientBalanceBefore == cBalanceBefore
            )
            : (
                reverted == true
                && cBalanceAfter == cBalanceBefore
                && recipientBalanceAfter == recipientBalanceBefore
            )
        );
    }

    receive() external payable { }
}

