contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // run takes recipient and amount to fund C before attempted withdrawal, and a boolean indicating whether
    // the test should attempt withdrawal as owner (true) or as non-owner (false).
    function run(address payable recipient, uint256 fundAmount, bool asOwner) public payable {
        require(address(this).balance >= fundAmount, "insufficient balance to fund");

        // Read initial observed data
        address initialOwner = c.owner();
        uint256 beforeC = address(c).balance;
        uint256 beforeRecipient = recipient.balance;

        // Fund the contract C by sending Ether from this test contract
        // (this is a state-changing call on C: via its fallback payable)
        c.f{value: fundAmount}();

        uint256 afterFundC = address(c).balance;
        // afterFundC should be beforeC + fundAmount
        // Now decide who will call withdrawAll: if asOwner==true, call from owner; otherwise call from a non-owner.
        // We cannot change msg.sender when calling c from here; but the InvMutTest contract deployed C, so
        // if initialOwner == address(this) then this contract is the owner. To simulate calling as owner or not,
        // require that when asOwner==true, initialOwner == address(this); when asOwner==false, initialOwner != address(this).
        // This keeps the test within a single transaction and uses only observable state.
        if (asOwner) {
            require(initialOwner == address(this), "to test owner path, this contract must be owner");
        } else {
            require(initialOwner != address(this), "to test non-owner path, this contract must not be owner");
        }

        // Attempt withdrawal and capture whether it reverted
        bool reverted;
        uint256 beforeRecipient2 = recipient.balance;
        uint256 beforeC2 = address(c).balance;
        try c.withdrawAll(recipient) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint256 afterC = address(c).balance;
        uint256 afterRecipient = recipient.balance;

        // General rule:
        // - If call was made by the owner (asOwner==true under the require above), withdrawAll must not revert,
        //   the contract balance must become zero, and the recipient's balance must increase by the withdrawn amount.
        // - If call was made by a non-owner (asOwner==false), withdrawAll must revert and balances must be unchanged.
        assert(
            (asOwner && !reverted && afterC == 0 && afterRecipient == beforeRecipient2 + beforeC2)
            || (!asOwner && reverted && afterC == beforeC2 && afterRecipient == beforeRecipient2)
        );
    }

    // accept Ether so this contract can fund C
    receive() external payable {}
}

