        address beforeOwner = c.owner();

        // fund C by sending Ether to its fallback (top-level call)
        (bool ok,) = address(c).call{value: fundAmount}("");
        require(ok);

        // balances before withdraw
        uint256 cBalBefore = address(c).balance;

        // enforce the desired relationship between caller and stored owner for the test
        if (callerIsOwner) {
            require(beforeOwner == address(this));
        } else {
            require(beforeOwner != address(this));
        }

        // perform the withdrawAll call as this contract (top-level try/catch)
        bool reverted;
        try c.withdrawAll(recipient) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // balances after withdraw
        uint256 cBalAfter = address(c).balance;

        // General rule:
        // - If this contract was owner (callerIsOwner==true), the call must not revert and C's balance must be zero.
        // - If this contract was not owner (callerIsOwner==false), the call must revert and C's balance must be unchanged.
        assert(
            (callerIsOwner && reverted == false && cBalAfter == 0) ||
            (!callerIsOwner && reverted == true && cBalAfter == cBalBefore)
        );
    }

    // allow receiving Ether when recipient is this contract
    receive() external payable { }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public test function taking inputs: the caller address is this contract (deployer of c),
    // so we vary the _recipient and a flag indicating whether the test should attempt to call as owner.
    // To call as owner we rely on the fact that c was deployed fresh with some owner; we cannot change msg.sender.
    // Instead we test both behaviors by observing whether c.owner() equals address(this).
    function run(address payable _recipient) public payable {
        require(true);

        // Read pre-state
        address beforeOwner = c.owner();
        uint256 beforeBalance = address(c).balance;

        // Attempt withdrawAll and record whether it reverted.
        bool reverted;
        try c.withdrawAll(_recipient) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Read post-state
        address afterOwner = c.owner();
        uint256 afterBalance = address(c).balance;

        // If caller (this contract) is not owner, call must revert and balances must be unchanged.
        // If caller is owner, call must not revert, owner stays same, and contract balance becomes zero.
        assert(
            (beforeOwner != address(this) && reverted && afterOwner == beforeOwner && afterBalance == beforeBalance)
            ||
            (beforeOwner == address(this) && !reverted && afterOwner == beforeOwner && afterBalance == 0)
        );
    }

    // allow receiving Ether when c transfers to this contract (not used but present)
    receive() external payable {}
}

