contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Try withdrawAll as the owner: take recipient and an amount to first fund C.
    // We fund C by sending ETH to it using the payable fallback from this contract.
    function run(address payable _recipient, uint256 fundAmount) public payable {
        require(_recipient != address(0));
        // ensure this test contract is the owner of c so the call should be allowed
        require(c.owner() == address(this));
        // ensure we have enough balance to fund C
        require(address(this).balance >= fundAmount);

        uint256 balBefore = address(c).balance;

        // Fund C by sending Ether to it
        // top-level state-changing call on c: use low-level transfer by calling payable address(c).call
        (bool sent,) = address(c).call{value: fundAmount}("\x00");
        // allow funding to fail (e.g., fundAmount == 0) but record new balance
        uint256 balAfterFund = address(c).balance;

        bool reverted;
        try c.withdrawAll(_recipient) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint256 balFinal = address(c).balance;

        // General rule (one assert): When owner calls withdrawAll, the owner remains unchanged
        // and the contract balance does not increase as a result of withdrawAll (i.e., balFinal <= balAfterFund).
        // Additionally, if the call did not revert then the contract balance must be zero afterwards.
        assert(c.owner() == address(this) && balFinal <= balAfterFund && (reverted || balFinal == 0));
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Params: recipient to receive funds from C, and fundAmount to pre-fund C.
    function run(address payable _recipient, uint256 fundAmount) public payable {
        require(_recipient != address(0));
        // This test assumes it is the owner so the call should be allowed by owner check.
        require(c.owner() == address(this));
        // Ensure this contract has enough Ether to fund C
        require(address(this).balance >= fundAmount);

        // Record balances before funding
        uint256 cBalBefore = address(c).balance;
        uint256 selfBalBefore = address(this).balance;

        // Fund C by calling its payable fallback via a direct call from this contract
        (bool ok,) = address(c).call{value: fundAmount}("\x00");
        // funding may succeed or fail; record resulting balances
        uint256 cBalAfterFund = address(c).balance;
        uint256 selfBalAfterFund = address(this).balance;

        bool reverted;
        // Owner calls withdrawAll; this is a top-level state-changing call on c
        try c.withdrawAll(_recipient) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint256 cBalFinal = address(c).balance;
        uint256 selfBalFinal = address(this).balance;

        // General rule:
        // - owner remains unchanged
        // - c's balance never increases as a result of withdrawAll (cBalFinal <= cBalAfterFund)
        // - if the call succeeded then c's balance is zero and the recipient (or this contract's balance change)
        //   reflects that at most all Ether was transferred out of C.
        // We can't observe recipient's balance directly, but we can observe this contract's balance change
        // (it may increase only if _recipient == address(this)). So we assert owner unchanged, c balance non-increasing,
        // and if call succeeded then c balance == 0. Additionally, if recipient is this contract, then its balance
        // should increase by exactly the amount withdrawn (cBalAfterFund - cBalFinal).

        assert(
            c.owner() == address(this)
            && cBalFinal <= cBalAfterFund
            && (reverted || cBalFinal == 0)
            && ( _recipient != address(this) || selfBalFinal == selfBalAfterFund + (cBalAfterFund - cBalFinal) )
        );
    }

    receive() external payable {}
}

contract InvMutTest {
